style.css:
@-moz-document domain("youtube.com") {
ytd-topbar-logo-renderer #logo-icon {
        display: block !important;
        width: 100px !important;
        height: 40px !important;

        background: url("https://cdn.phototourl.com/free/2026-07-26-d676faf7-885d-4598-ad30-c0ced86ae550.gif")
            center bottom / 78px auto no-repeat !important;
    }

    ytd-topbar-logo-renderer #logo-icon svg,
    ytd-topbar-logo-renderer #logo-icon yt-icon {
        display: none !important;
    }
}
